<h2 class="mb-3">Tạo tài khoản khách hàng</h2><form method="post" action="<?= htmlspecialchars(BASE_URL . '/accounts/store') ?>" class="card p-3"><div class="mb-3"><label class="form-label">Tên tài khoản</label><input class="form-control <?= !empty($errors['username']) ? 'is-invalid' : '' ?>" name="username" value="<?= htmlspecialchars((string) ($old['username'] ?? '')) ?>"><?php if (!empty($errors['username'])): ?><div class="invalid-feedback"><?= htmlspecialchars($errors['username']) ?></div><?php endif; ?></div><div class="mb-3"><label class="form-label">Tên hiển thị</label><input class="form-control <?= !empty($errors['display_name']) ? 'is-invalid' : '' ?>" name="display_name" value="<?= htmlspecialchars((string) ($old['display_name'] ?? '')) ?>"><?php if (!empty($errors['display_name'])): ?><div class="invalid-feedback"><?= htmlspecialchars($errors['display_name']) ?></div><?php endif; ?></div><div class="mb-3"><label class="form-label">Mật khẩu/PIN</label><input type="password" class="form-control <?= !empty($errors['password']) ? 'is-invalid' : '' ?>" name="password"><?php if (!empty($errors['password'])): ?><div class="invalid-feedback"><?= htmlspecialchars($errors['password']) ?></div><?php endif; ?></div><button class="btn btn-primary" type="submit">Tạo tài khoản</button></form>
